import{_ as a,o as i,c as t,a5 as r}from"./chunks/framework.Bt0SrEfo.js";const b=JSON.parse('{"title":"💡 旅行 Tips","description":"","frontmatter":{"title":"💡 旅行 Tips","tags":["旅游","Tips","经验"]},"headers":[],"relativePath":"旅游计划/旅行Tips.md","filePath":"旅游计划/旅行Tips.md","lastUpdated":1789692648000}'),e={name:"旅游计划/旅行Tips.md"};function o(n,l,d,s,h,u){return i(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="💡-旅行-tips" tabindex="-1">💡 旅行 Tips <a class="header-anchor" href="#💡-旅行-tips" aria-label="Permalink to &quot;💡 旅行 Tips&quot;">​</a></h1><blockquote><p>旅行中积累的实用经验，持续更新。</p></blockquote><h2 id="🎒-打包清单" tabindex="-1">🎒 打包清单 <a class="header-anchor" href="#🎒-打包清单" aria-label="Permalink to &quot;🎒 打包清单&quot;">​</a></h2><h3 id="通用原则" tabindex="-1">通用原则 <a class="header-anchor" href="#通用原则" aria-label="Permalink to &quot;通用原则&quot;">​</a></h3><ul><li><strong>3-1-1 法则</strong>：随身 3oz 液体、1 袋、1 件（飞机）</li><li><strong>七分打包法</strong>：带 7 天换洗衣服，剩 1 天靠洗 / 晾</li><li><strong>重要物品随身</strong>：身份证、手机、充电宝、钱包</li><li><strong>衣物分装袋</strong>：按类别装，便于查找</li></ul><h3 id="自驾专用" tabindex="-1">自驾专用 <a class="header-anchor" href="#自驾专用" aria-label="Permalink to &quot;自驾专用&quot;">​</a></h3><ul><li>驾照 + 备用钥匙</li><li>行车记录仪（必装）</li><li>应急工具包（拖车绳 / 充气泵）</li><li>车载充电器</li><li>应急食品 + 水</li></ul><h2 id="✈️-机票预订" tabindex="-1">✈️ 机票预订 <a class="header-anchor" href="#✈️-机票预订" aria-label="Permalink to &quot;✈️ 机票预订&quot;">​</a></h2><h3 id="提前多久买" tabindex="-1">提前多久买？ <a class="header-anchor" href="#提前多久买" aria-label="Permalink to &quot;提前多久买？&quot;">​</a></h3><ul><li>国内：<strong>提前 1-2 个月</strong></li><li>港澳台 / 东亚：<strong>提前 2-3 个月</strong></li><li>长途国际：<strong>提前 3-6 个月</strong></li></ul><h3 id="比价工具" tabindex="-1">比价工具 <a class="header-anchor" href="#比价工具" aria-label="Permalink to &quot;比价工具&quot;">​</a></h3><ul><li>Skyscanner（天巡）</li><li>Google Flights</li><li>飞猪 / 携程（国内）</li></ul><h3 id="省钱技巧" tabindex="-1">省钱技巧 <a class="header-anchor" href="#省钱技巧" aria-label="Permalink to &quot;省钱技巧&quot;">​</a></h3><ul><li><strong>联程机票</strong>比多段便宜</li><li>周二 / 周三出发最便宜</li><li>关注航司会员日（南航每月 28 日等）</li><li>用 <strong>X 公司里程</strong> 兑换</li></ul><h2 id="🏨-住宿选择" tabindex="-1">🏨 住宿选择 <a class="header-anchor" href="#🏨-住宿选择" aria-label="Permalink to &quot;🏨 住宿选择&quot;">​</a></h2><h3 id="平台" tabindex="-1">平台 <a class="header-anchor" href="#平台" aria-label="Permalink to &quot;平台&quot;">​</a></h3><ul><li>携程 / 美团（国内首选）</li><li>Booking / Agoda（国际）</li><li>Airbnb（公寓）</li><li>青旅（穷游）</li></ul><h3 id="选住宿要点" tabindex="-1">选住宿要点 <a class="header-anchor" href="#选住宿要点" aria-label="Permalink to &quot;选住宿要点&quot;">​</a></h3><ul><li>📍 位置 &gt; 设施</li><li>🚇 交通便利</li><li>🛡️ 安全（看真实评论）</li><li>🍜 附近餐饮</li></ul><h2 id="🛡️-安全提醒" tabindex="-1">🛡️ 安全提醒 <a class="header-anchor" href="#🛡️-安全提醒" aria-label="Permalink to &quot;🛡️ 安全提醒&quot;">​</a></h2><ul><li>身份证 / 护照拍照备份（云端）</li><li>给家人留行程表</li><li>购买旅游意外险（10-30 元 / 天）</li><li>大额现金分散放</li><li>注意当地诈骗（黑车 / 黑导游）</li></ul><h2 id="📸-摄影建议" tabindex="-1">📸 摄影建议 <a class="header-anchor" href="#📸-摄影建议" aria-label="Permalink to &quot;📸 摄影建议&quot;">​</a></h2><ul><li>早起 / 傍晚光线最好（Golden Hour）</li><li>三脚架拍星空 / 长曝光</li><li>充电电池多备</li><li>重要照片立即备份</li></ul><h2 id="💰-预算技巧" tabindex="-1">💰 预算技巧 <a class="header-anchor" href="#💰-预算技巧" aria-label="Permalink to &quot;💰 预算技巧&quot;">​</a></h2><ul><li>行李自带水杯（机场 / 酒店都省）</li><li>自己做饭（民宿）</li><li>用当地公交代替打车</li><li>景点提前查免费 / 折扣日</li></ul><h2 id="🌐-必备-app" tabindex="-1">🌐 必备 App <a class="header-anchor" href="#🌐-必备-app" aria-label="Permalink to &quot;🌐 必备 App&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>App</th></tr></thead><tbody><tr><td>地图</td><td>高德 / Google Maps</td></tr><tr><td>翻译</td><td>Google 翻译 / DeepL</td></tr><tr><td>行程</td><td>穷游 / 马蜂窝</td></tr><tr><td>美食</td><td>大众点评 / TripAdvisor</td></tr><tr><td>天气</td><td>彩云天气 / 中央气象台</td></tr><tr><td>记账</td><td>鲨鱼记账 / Money Pro</td></tr></tbody></table><h2 id="📚-推荐的旅行书-纪录片" tabindex="-1">📚 推荐的旅行书 / 纪录片 <a class="header-anchor" href="#📚-推荐的旅行书-纪录片" aria-label="Permalink to &quot;📚 推荐的旅行书 / 纪录片&quot;">​</a></h2><ul><li>《孤独星球》（Lonely Planet）系列</li><li>《国家地理》杂志</li><li>纪录片《航拍中国》</li><li>纪录片《地球脉动》</li></ul><h2 id="🔄-旅行复盘模板" tabindex="-1">🔄 旅行复盘模板 <a class="header-anchor" href="#🔄-旅行复盘模板" aria-label="Permalink to &quot;🔄 旅行复盘模板&quot;">​</a></h2><p>每次旅行结束后：</p><ol><li><strong>满意度评分</strong>（1-10）</li><li><strong>超预期的事</strong>：___</li><li><strong>翻车的事</strong>：___</li><li><strong>下次避免</strong>：___</li><li><strong>推荐给别人</strong>：是 / 否</li></ol>',32)])])}const p=a(e,[["render",o]]);export{b as __pageData,p as default};
